import SwiftUI

public struct ResearchHeader: View {
    let company: CompanyProfile?; let quote: Quote?; let isFavorite: Bool; let lastUpdated: Date?; let onRefresh: () -> Void; let onFavorite: () -> Void
    public var body: some View { HStack { VStack(alignment: .leading, spacing: 4) { HStack { Text(company?.symbol ?? "Research").font(.system(size: 28, weight: .bold, design: .rounded)); Button(action: onFavorite) { Image(systemName: isFavorite ? "star.fill" : "star").foregroundStyle(isFavorite ? .yellow : .secondary) }.buttonStyle(.plain).accessibilityLabel(isFavorite ? "Remove favorite" : "Add favorite") }; Text(company?.name ?? "Professional investment research").font(.subheadline).foregroundStyle(.secondary) }; Spacer(); VStack(alignment: .trailing) { Text(quote?.price.formatted(.currency(code: quote?.currency ?? "USD")) ?? "Unavailable").font(.title2.weight(.semibold)); Text(quote?.changePercent.formatted(.percent) ?? "Unavailable").foregroundStyle(quote.map { $0.changePercent >= 0 ? Color.green : Color.red } ?? Color.secondary).font(.subheadline) }; if let lastUpdated { Text(lastUpdated.formatted(date: .omitted, time: .shortened)).font(.caption).foregroundStyle(.tertiary) }; Button(action: onRefresh) { Image(systemName: "arrow.clockwise") }.buttonStyle(.bordered).controlSize(.small).accessibilityLabel("Refresh research") }.accessibilityIdentifier("research.header") }
}
